const tabId = 1962625065;

const all23 = await browserjs(tabId, () => {
  // Let's find each listing card on the page
  // We can group by contact button or listing container
  const contactButtons = Array.from(document.querySelectorAll('button[id^="contact-"]'));

  return contactButtons.map(btn => {
    const pid = btn.id.replace('contact-', '');
    // Find the closest card container
    let container = btn;
    while (container && !container.querySelector(`a[href*="${pid}"]`) && container !== document.body) {
      container = container.parentElement;
    }
    // If not found, go up 5 levels
    if (!container || container === document.body) {
      container = btn.parentElement.parentElement.parentElement.parentElement;
    }

    // Find all links and text in container
    const links = Array.from(container.querySelectorAll('a')).map(a => ({
      text: a.textContent.trim().replace(/\s+/g, ' '),
      href: a.href
    }));

    // Let's extract text
    const text = container.innerText;

    return {
      pid,
      text: text.slice(0, 500),
      links: links.filter(l => l.text.length > 0)
    };
  });
});

console.log(`Found ${all23.length} listing cards.`);
console.log(JSON.stringify(all23.slice(0, 5), null, 2));

