const sortedListings = await browserjs(tabId, () => {
  const contactButtons = Array.from(document.querySelectorAll('button[id^="contact-"]'));

  return contactButtons.map((btn, index) => {
    const pid = btn.id.replace('contact-', '');
    let container = btn;
    while (container && !container.querySelector(`a[href*="${pid}"]`) && container !== document.body) {
      container = container.parentElement;
    }
    if (!container || container === document.body) {
      container = btn.parentElement.parentElement.parentElement.parentElement;
    }

    const text = container.innerText;
    const detailLink = container.querySelector(`a[href*="/pid/${pid}"]`)?.href;
    const sellerLink = container.querySelector('a[href*="/profile/"]');
    const sellerName = sellerLink ? sellerLink.innerText.trim().replace(/\n/g, ' - ') : null;

    return {
      rank: index + 1,
      pid,
      detailLink,
      sellerName,
      text: text.slice(0, 300)
    };
  });
});

console.log(JSON.stringify(sortedListings.slice(0, 10), null, 2));
